script.text:

function load$Grid(g) {
	g.add_onResponseComplete(on$GridServicesPurchaseInvoice$ResponseComplete);
	g.add_commandEvent(on$GridServicesPurchaseInvoice$ExecuteCommand);
	&ddScriptGridLoad;
	&MultiViewer.Loading;
}
function dispose$Grid(g) {
&MultiViewer.Dispose.Script;
	try {g.remove_commandEvent(on$GridServicesPurchaseInvoice$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridServicesPurchaseInvoice$ResponseComplete);} catch (ex) {}
	&ddScriptGridDispose;
}
function on$GridServicesPurchaseInvoice$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender;
	switch (action) {
		case 'ImportData':
			&NoticeExecuteCommand;
			break;
		case 'Download':
			&UserDefinedDownload;
		case 'AfterRemoveRow':
			&MultiViewer.AfterRemoveRow;
			break;
		&MultiViewer.RowColChange;	
			break;
		default:
			break;
	}
}
function on$GridServicesPurchaseInvoice$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object;
	switch (context) {
		case 'Download':
			g._key = result[0].Value;
			break;
		&NoticeResponseComplete;
		&ddScriptGridResponseComplete;
		default:
			break;
	}
}
&ddScriptGridRender;
function show$Form(g, c) {
	(g._authorize == 1) && (!g._denyNew) ? g.showForm(c) : $message.show(g._denyMessage ? g._denyMessage : $df.getResources(g._language, "Message.NotAccess"));
}

			&DowloadScript;
			&PrintRightScript;
			&NoticeScript;
			&FlowMultiScript;
			&VisibleFieldScript;
			&MultiViewer.Script;
